import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private byte readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') {
                ptr++;
            }
            return hasNextByte();
        }

        public int nextInt() {
            if (!hasNext()) throw new RuntimeException("No more input");
            int n = 0;
            byte b = readByte();
            boolean minus = false;
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            while (b >= '0' && b <= '9') {
                n = n * 10 + (b - '0');
                b = readByte();
            }
            return minus ? -n : n;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        if (!sc.hasNext()) return;

        int n = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();

        long[] pref = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            pref[i] = pref[i - 1] + sc.nextInt();
        }

        long totalSum = pref[n];

        // dp[i] armazenará a menor soma coberta usando j etiquetas nos primeiros i elementos.
        long[] prevDp = new long[n + 1];
        long[] currDp = new long[n + 1];

        // Para j = 1..k
        int rem = n - k * c;

        for (int j = 1; j <= k; j++) {
            int start = j * c;
            int end = start + rem;

            long minVal = Long.MAX_VALUE;
            for (int i = start; i <= end; i++) {
                // Se colocamos uma etiqueta terminando em i:
                long sumCovered = pref[i] - pref[i - c];
                long candidate = prevDp[i - c] + sumCovered;
                if (candidate < minVal) {
                    minVal = candidate;
                }
                currDp[i] = minVal;
            }

            // Troca os buffers para a próxima iteração
            long[] tmp = prevDp;
            prevDp = currDp;
            currDp = tmp;
        }

        long minCovered = prevDp[n];
        long maxUncovered = totalSum - minCovered;

        System.out.println(maxUncovered);
    }
}
